       failed_operation, current_revision, version, created_by, created_at
FROM knowledge_data.governed_data_source
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND id = #{id}
FOR UPDATE

mapper.update:

